$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host " MemeScope Stage 17 - Telegram Bot + Signal Channel" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host ""

$root = (Get-Location).Path
$utf8 = New-Object System.Text.UTF8Encoding($false)

$recorderRelative = "src/lib/signal-recorder-db.ts"
$recorderPath = Join-Path $root $recorderRelative

if (!(Test-Path -LiteralPath $recorderPath)) {
    throw "Required file not found: $recorderRelative"
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $env:TEMP "MemeScope-Stage17-$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null
Copy-Item -LiteralPath $recorderPath -Destination (Join-Path $backup "signal-recorder-db.ts.bak") -Force

Write-Host "Backup created: $backup" -ForegroundColor DarkGray

$recorder = [System.IO.File]::ReadAllText($recorderPath)

# Narrow Stage 17 patch: publisher runs after each successful recorder pass.
$telegramMarker = "Stage 17 Telegram publisher"

if (!$recorder.Contains($telegramMarker)) {
    $returnMarker = @'
  return {
    generatedAt: Date.now(),
'@

    $idx = $recorder.IndexOf($returnMarker)

    if ($idx -lt 0) {
        throw "Recorder return marker not found. No project source was modified."
    }

$publisherBlock = @'
  // Stage 17 Telegram publisher.
  // Telegram failures must never break the signal recorder itself.
  try {
    const {
      publishPendingTelegramSignals,
    } =
      await import(
        "@/lib/telegram-publisher"
      );

    await publishPendingTelegramSignals();
  } catch (error) {
    console.error(
      "Telegram signal publisher failed:",
      error,
    );
  }

'@

    $recorder =
        $recorder.Substring(0, $idx) +
        $publisherBlock +
        $recorder.Substring($idx)

    if (!$recorder.Contains($telegramMarker)) {
        throw "Recorder validation failed. No project source was modified."
    }
} else {
    Write-Host "Recorder Telegram hook already exists." -ForegroundColor Yellow
}

$payloads = @{}

$payloads["src/lib/telegram.ts"] = @"

"@

$payloads["src/lib/telegram-publisher.ts"] = @"

"@

$payloads["src/app/api/telegram/webhook/route.ts"] = @"

"@

$payloads["src/app/api/telegram/bootstrap/route.ts"] = @"

"@

$payloads["src/app/api/telegram/status/route.ts"] = @"

"@

$payloads["src/app/api/telegram/test/route.ts"] = @"

"@

$payloads["src/app/api/telegram/cron/route.ts"] = @"

"@

function Write-Base64File {
  param(
    [Parameter(Mandatory=$true)][string]$RelativePath,
    [Parameter(Mandatory=$true)][string]$Base64Text
  )

  $full = Join-Path $root $RelativePath
  $parent = Split-Path -Parent $full
  New-Item -ItemType Directory -Force -Path $parent | Out-Null

  $bytes = [Convert]::FromBase64String(
    ($Base64Text -replace '\s', '')
  )

  [System.IO.File]::WriteAllBytes(
    $full,
    $bytes
  )

  Write-Host "Created: $RelativePath" -ForegroundColor Green
}

foreach ($item in $payloads.GetEnumerator()) {
  Write-Base64File `
    -RelativePath $item.Key `
    -Base64Text $item.Value
}

[System.IO.File]::WriteAllText(
  $recorderPath,
  $recorder,
  $utf8
)

Write-Host "Updated: $recorderRelative" -ForegroundColor Green

# Convenience documentation/examples only.
$readmePath = Join-Path $root "README-STAGE17.md"
$cronExamplePath = Join-Path $root "vercel.pro-cron.example.json"

[System.IO.File]::WriteAllBytes(
  (Join-Path $root "README-STAGE17.md"),
  [Convert]::FromBase64String(@"

"@ -replace '\s', '')
)
Write-Host "Created: README-STAGE17.md" -ForegroundColor Green

[System.IO.File]::WriteAllBytes(
  (Join-Path $root "vercel.pro-cron.example.json"),
  [Convert]::FromBase64String(@"
ewogICJjcm9ucyI6IFsKICAgIHsKICAgICAgInBhdGgiOiAiL2FwaS90ZWxlZ3JhbS9jcm9uIiwKICAgICAgInNjaGVkdWxlIjogIiogKiAqICogKiIKICAgIH0KICBdCn0K
"@ -replace '\s', '')
)
Write-Host "Created: vercel.pro-cron.example.json" -ForegroundColor Green

Remove-Item -Recurse -Force (Join-Path $root ".next") -ErrorAction SilentlyContinue

Write-Host ""
Write-Host "==================================================" -ForegroundColor Green
Write-Host " Stage 17 installed" -ForegroundColor Green
Write-Host "==================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Next:" -ForegroundColor Cyan
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host ""
Write-Host "Then add Telegram env vars in Vercel and redeploy." -ForegroundColor Yellow
Write-Host "Read README-STAGE17.md for BotFather, channel admin, bootstrap and test commands."
Write-Host ""
